{"command":"cd /workspace && ft2 call module_load '{"path":"/workspace/work/tune_base.xm"}' >/dev/null && python3 - <<'PY'
import subprocess, json

def getcell(r,c):
    out=subprocess.check_output(['bash','-lc',f"cd /workspace && ft2 call pattern_get_cell '{{\"pattern\":7,\"row\":{r},\"channel\":{c}}}'"], text=True)
    data=json.loads(json.loads(out.splitlines()[0])['content'][0]['text'])
    return data
for row in range(48,64):
    vals=[]
    for ch in range(8):
        d=getcell(row,ch)
        if d['note'] or d['instrument'] or d['volume'] or d['effect'] or d['effect_param']:
            vals.append((ch,d['note_name'],d['instrument'],d['volume']))
    print(row, vals)
PY"}

